import React, { useState, useEffect } from 'react';
import { createUser, getUsers, deleteUser, updateUser, getFranchises } from '../services/api';
import { Button, TextField, Grid, Box, Typography, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Select, MenuItem } from '@mui/material';

const CreateUserSuperAdmin = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    name: '',
    role: 'user',
    franchiseId: '',
  });

  const [franchises, setFranchises] = useState([]);
  const [users, setUsers] = useState([]);
  const [editingUser, setEditingUser] = useState(null);
  const [isSuperAdminExists, setIsSuperAdminExists] = useState(false);

  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data);
      } catch (error) {
        alert('Error fetching franchises: ' + (error.response?.data?.message || error.message));
      }
    };

    const fetchUsers = async () => {
      try {
        const response = await getUsers();
        setUsers(response);
      } catch (error) {
        alert('Error fetching users: ' + (error.response?.data?.message || error.message));
      }
    };

    fetchFranchises();
    fetchUsers();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (formData.role === 'superadmin' && isSuperAdminExists) {
      alert('Only one superadmin can be created for all franchises.');
      return;
    }

    try {
      if (editingUser) {
        await updateUser(editingUser._id, formData);
        alert('User updated successfully!');
      } else {
        await createUser(formData);
        alert('User created successfully!');
      }

      setEditingUser(null);
      setFormData({ username: '', password: '', name: '', role: 'user', franchiseId: '' });

      const response = await getUsers();
      setUsers(response);
    } catch (error) {
      alert('Error creating/updating user: ' + (error.response?.data?.message || error.message));
    }
  };

  const handleEdit = (user) => {
    setEditingUser(user);
    setFormData({
      username: user.username,
      password: '',
      name: user.name,
      role: user.role,
      franchiseId: user.franchiseId || '',
    });
  };

  const handleDelete = async (userId) => {
    try {
      await deleteUser(userId);
      alert('User deleted successfully!');
      
      const response = await getUsers();
      setUsers(response);
    } catch (error) {
      alert('Failed to delete user. Please try again.');
    }
  };

  const isEditingSelf = editingUser && editingUser.role === 'superadmin';

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 'bold', marginBottom: 3 }}>Create or Edit User</Typography>

      <Paper sx={{ padding: 3, marginBottom: 4 }}>
        <form onSubmit={handleSubmit}>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <TextField
                label="Username"
                name="username"
                value={formData.username}
                onChange={handleChange}
                fullWidth
                required
                variant="outlined"
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="Password"
                name="password"
                type="password"
                value={formData.password}
                onChange={handleChange}
                fullWidth
                required={!editingUser}
                variant="outlined"
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="Name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                fullWidth
                required
                variant="outlined"
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              {editingUser ? (
                <>
                  <Typography variant="body2" sx={{ marginBottom: 1 }}>
                    Current Role: {editingUser.role}
                  </Typography>
                  <Select
                    name="role"
                    value={formData.role}
                    onChange={handleChange}
                    fullWidth
                    required
                    variant="outlined"
                    disabled={isEditingSelf}
                  >
                    <MenuItem value="user">User</MenuItem>
                    <MenuItem value="admin">Admin</MenuItem>
                  </Select>
                </>
              ) : (
                <Select
                  name="role"
                  value={formData.role}
                  onChange={handleChange}
                  fullWidth
                  required
                  variant="outlined"
                >
                  <MenuItem value="user">User</MenuItem>
                  <MenuItem value="admin">Admin</MenuItem>
                </Select>
              )}
            </Grid>
            <Grid item xs={12}>
              {editingUser ? (
                <>
                  <Typography variant="body2" sx={{ marginBottom: 1 }}>
                    Current Franchise: {editingUser.franchise?.name || 'None'}
                  </Typography>
                  <Select
                    name="franchiseId"
                    value={formData.franchiseId}
                    onChange={handleChange}
                    fullWidth
                    required
                    variant="outlined"
                    disabled={isEditingSelf}
                  >
                    <MenuItem value="">Select a Franchise</MenuItem>
                    {franchises.map((franchise) => (
                      <MenuItem key={franchise._id} value={franchise._id}>
                        {franchise.name} - {franchise.location}
                      </MenuItem>
                    ))}
                  </Select>
                </>
              ) : (
                <Select
                  name="franchiseId"
                  value={formData.franchiseId}
                  onChange={handleChange}
                  fullWidth
                  required
                  variant="outlined"
                >
                  <MenuItem value="">Select a Franchise</MenuItem>
                  {franchises.map((franchise) => (
                    <MenuItem key={franchise._id} value={franchise._id}>
                      {franchise.name} - {franchise.location}
                    </MenuItem>
                  ))}
                </Select>
              )}
            </Grid>
            <Grid item xs={12}>
              <Button type="submit" variant="contained" color="primary" sx={{ marginRight: 2 }}>
                {editingUser ? 'Update User' : 'Create User'}
              </Button>
              {editingUser && (
                <Button variant="outlined" color="secondary" onClick={() => setEditingUser(null)}>
                  Cancel
                </Button>
              )}
            </Grid>
          </Grid>
        </form>
      </Paper>

      <Typography variant="h5" sx={{ fontWeight: 'bold', marginBottom: 2 }}>All Users</Typography>
      
      <TableContainer component={Paper} sx={{ width: '100%' }}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell sx={{ fontWeight: 'bold', fontSize: '1.1rem' }}>Username</TableCell>
              <TableCell sx={{ fontWeight: 'bold', fontSize: '1.1rem' }}>Name</TableCell>
              <TableCell sx={{ fontWeight: 'bold', fontSize: '1.1rem' }}>Role</TableCell>
              <TableCell sx={{ fontWeight: 'bold', fontSize: '1.1rem' }}>Franchise</TableCell>
              <TableCell sx={{ fontWeight: 'bold', fontSize: '1.1rem' }}>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {users.length > 0 ? (
              users.map((user) => {
                const franchiseName = user.franchise ? user.franchise.name : 'N/A';
                return (
                  <TableRow key={user._id}>
                    <TableCell>{user.username}</TableCell>
                    <TableCell>{user.name}</TableCell>
                    <TableCell>{user.role}</TableCell>
                    <TableCell>{franchiseName}</TableCell>
                    <TableCell>
                      <Button onClick={() => handleEdit(user)} color="primary" size="small">Edit</Button>
                      <Button onClick={() => handleDelete(user._id)} color="error" size="small" sx={{ marginLeft: 1 }}>Delete</Button>
                    </TableCell>
                  </TableRow>
                );
              })
            ) : (
              <TableRow>
                <TableCell colSpan={5} align="center">No users available</TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default CreateUserSuperAdmin;
